//! Hypoid and spiral bevel gears, generated the way they are cut.
//!
//! The ring gear is Formate: each tooth slot is exactly what a face-mill
//! cutter leaves when plunged without rolling, a surface of revolution
//! about the cutter axis (straight blades at the pressure angle, a flat
//! point and rounded corners). The pinion is then generated by the ring
//! gear itself: rolling the pair through mesh, every point of pinion blank
//! that the ring gear's teeth pass through is cut away. What survives is
//! the exact envelope of the ring teeth, so the pair is conjugate by
//! construction, root fillets and any undercut included. A clearance is
//! added to the generating ring's tip and root so the pinion's root and
//! tip stand clear of the real ring gear.
//!
//! With no offset the shafts intersect and the pair is a spiral bevel.
//! With an offset (the pinion axis passing above or below the ring axis,
//! as in a car's final drive) it is a hypoid.
//!
//! Design frame: the ring gear's axis is +z through the origin, which is
//! both the ring's pitch apex and the crossing point (the foot of the
//! common perpendicular of the two shafts). The pinion axis runs along
//! (sin Σ, 0, cos Σ) through (0, E, 0).
//!
//! Each gear is described in its own frame (pitch apex at the origin, axis
//! +z) by sections: cones square to the pitch cone at cone distance s,
//! points on them at depth t along the pitch cone's outward normal. On
//! each section a tooth is an arc of azimuth at every depth, found by
//! solving where the generating body begins.

use crate::reach;
use serde::{Deserialize, Serialize};
use std::f64::consts::{PI, TAU};

/// Which half of a hypoid set a gear is.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Role {
    Pinion,
    Ring,
}

/// What a hypoid or spiral bevel set is made from.
#[derive(Clone, Debug, PartialEq)]
pub struct Spec {
    pub pinion_teeth: u32,
    pub ring_teeth: u32,
    /// Ring gear's outer (heel) transverse module, mm.
    pub module: f64,
    pub pressure_angle: f64,
    /// Ring gear face width along its pitch cone, mm.
    pub face: f64,
    /// Shaft offset E, mm; positive is the usual car arrangement, the
    /// pinion below the ring's centre with a left-hand pinion.
    pub offset: f64,
    /// Angle between the shafts, degrees.
    pub shaft_angle: f64,
    /// Pinion mean spiral angle, degrees.
    pub spiral: f64,
    /// Use the less common hand for this offset.
    pub reverse_hand: bool,
    /// Face-mill cutter radius, mm; 0 picks one to suit the gear.
    pub cutter_radius: f64,
    /// Thinning of the ring gear's teeth, normal circular mm.
    pub backlash: f64,
    pub pinion_bore: f64,
    pub ring_bore: f64,
    /// Ball end mill Ø, mm, that rounds the roots of both gears; 0 if
    /// none is chosen (then the cutter's usual edge radius).
    pub ball: f64,
    /// Nozzle Ø, mm, of the 3D printer the gears are made on: every tooth
    /// surface is eroded by a quarter of it (the bores above are already
    /// widened by half of it); 0 when they are not printed.
    pub nozzle: f64,
}

// ---- small vector helpers ---------------------------------------------------

type V3 = [f64; 3];

fn add(a: V3, b: V3) -> V3 {
    [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
}
fn sub(a: V3, b: V3) -> V3 {
    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
}
fn mul(k: f64, a: V3) -> V3 {
    [k * a[0], k * a[1], k * a[2]]
}
fn dot(a: V3, b: V3) -> f64 {
    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
}
fn cross(a: V3, b: V3) -> V3 {
    [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
}
fn norm(a: V3) -> f64 {
    dot(a, a).sqrt()
}
fn unit(a: V3) -> V3 {
    mul(1.0 / norm(a).max(1e-300), a)
}

// ---- pitch design -----------------------------------------------------------

/// The steepest ring pitch cone, degrees: a bevel worm's wheel comes close
/// to a face gear.
const MAX_RING_PITCH: f64 = 89.0;

/// The solved pair, in the design frame.
#[derive(Clone, Debug, PartialEq)]
pub struct Design {
    pub spec: Spec,
    /// Mean point, where the pitch cones touch, and the common normal
    /// there (pointing out of the ring gear, into the pinion).
    pub p: V3,
    pub n: V3,
    /// Tooth line direction at the mean point, towards the ring's heel.
    pub t: V3,
    /// Ring and pinion pitch cone angles, radians.
    pub ring_pitch: f64,
    pub pinion_pitch: f64,
    /// Pinion pitch apex and axis.
    pub pinion_apex: V3,
    pub pinion_axis: V3,
    /// Pinion frame's x axis: towards the mean point.
    pub pinion_x: V3,
    /// Mean spiral angles in each gear's own frame (signed), radians.
    pub ring_spiral: f64,
    pub pinion_spiral: f64,
    /// Mean pitch radii and cone distances.
    pub ring_radius: f64,
    pub pinion_radius: f64,
    pub ring_cone: f64,
    pub pinion_cone: f64,
    /// θ_pinion = sense · (z_ring / z_pinion) · θ_ring.
    pub sense: f64,
    /// Mean normal module, working depth, clearance, addenda, dedenda.
    pub mn: f64,
    pub depth: f64,
    pub clearance: f64,
    pub ring_addendum: f64,
    pub pinion_addendum: f64,
    pub ring_dedendum: f64,
    pub pinion_dedendum: f64,
    /// Ring gear's mean normal tooth thickness on the pitch surface.
    pub ring_thickness: f64,
    /// Ring outer and inner cone distances.
    pub ring_outer: f64,
    pub ring_inner: f64,
    pub cutter: Cutter,
    /// Slot 0's middle azimuth by distance from the apex, for finding the
    /// slots near a point.
    slot_table: Vec<(f64, f64)>,
    /// How far the ring's slot floors are raised, at cone distances
    /// evenly spaced from its toe to its heel, so the ball end mill can
    /// get down to them (see `members`). Empty: not raised.
    pub floor: Vec<f64>,
}

/// A Formate cutter, in the ring gear's frame, set to cut slot 0.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Cutter {
    /// Centre of the blade tips' circle and the axis out of the gear.
    pub center: V3,
    pub axis: V3,
    /// Reference direction round the axis: towards the mean point.
    pub x: V3,
    pub radius: f64,
    /// Slot width (normal) on the pitch line, and the pitch line's
    /// height above the blade tips.
    pub width: f64,
    pub pitch_height: f64,
    pub alpha: f64,
    /// Blade edge radius.
    pub edge: f64,
}

struct Trial {
    res: [f64; 2],
    design: Option<Design>,
}

fn pitch_apex(p: V3, g: V3, l0: V3, d: V3) -> V3 {
    // Where the line p - μ g meets the axis l0 + λ d (they share a plane).
    // Least squares on μ, λ.
    let w = sub(p, l0);
    let (a, b, c) = (dot(g, g), dot(g, d), dot(d, d));
    let (e, f) = (dot(g, w), dot(d, w));
    let den = a * c - b * b;
    let mu = (c * e - b * f) / den;
    sub(p, mul(mu, g))
}

impl Spec {
    /// The biggest ball end mill Ø that cuts both gears' roots.
    pub fn largest_ball(&self) -> Option<f64> {
        let fits = |d: f64| Spec { ball: d, ..self.clone() }.design().is_some_and(|g| g.ball_trouble().is_none());
        let mut lo = 0.0;
        let mut hi = self.module;
        if !fits(1e-3 * self.module) {
            return None;
        }
        while fits(hi) && hi < 4.0 * self.module {
            lo = hi;
            hi *= 1.5;
        }
        for _ in 0..30 {
            let mid = (lo + hi) / 2.0;
            if fits(mid) { lo = mid } else { hi = mid }
        }
        Some(lo)
    }

    fn ring_outer_radius(&self) -> f64 {
        self.module * self.ring_teeth as f64 / 2.0
    }

    fn offset_line(&self) -> (V3, V3) {
        let s = self.shaft_angle.to_radians();
        ([0.0, self.offset, 0.0], [s.sin(), 0.0, s.cos()])
    }

    /// Spiral-bevel starting cone (no offset): the classic rolling cones.
    fn bevel_cone(&self) -> f64 {
        let s = self.shaft_angle.to_radians();
        let (zp, zg) = (self.pinion_teeth as f64, self.ring_teeth as f64);
        let dp = s.sin().atan2(zg / zp + s.cos());
        s - dp
    }

    /// Everything that follows from a mean point at azimuth η on a ring
    /// pitch cone of angle Γ. `tooth` gives the tooth line when the pitch
    /// cones roll without sliding (no offset), else it follows from the
    /// sliding velocity.
    fn trial(&self, eta: f64, gam: f64, hand: f64, tooth: Option<f64>) -> Trial {
        let fail = Trial { res: [1e3, 1e3], design: None };
        if !(0.02..PI - 0.02).contains(&gam) {
            return fail;
        }
        let rg = self.ring_outer_radius() - self.face / 2.0 * gam.sin();
        if rg <= 0.0 {
            return fail;
        }
        let am = rg / gam.sin();
        let p = [am * gam.sin() * eta.cos(), am * gam.sin() * eta.sin(), am * gam.cos()];
        let n = [gam.cos() * eta.cos(), gam.cos() * eta.sin(), -gam.sin()];
        let (l0, d) = self.offset_line();
        let arm = sub(p, l0);
        let m = cross(d, arm);
        if norm(m) < 1e-9 * am {
            return fail;
        }
        let r1 = dot(n, unit(m));
        // Pinion generator: in its meridian plane, square to the normal,
        // pointing along its axis.
        let mut gp = unit(cross(m, n));
        if dot(gp, d) < 0.0 {
            gp = mul(-1.0, gp);
        }
        let apex = pitch_apex(p, gp, l0, d);
        let gg = unit(p);
        let (zp, zg) = (self.pinion_teeth as f64, self.ring_teeth as f64);
        let vg = cross([0.0, 0.0, 1.0], p);
        let vp_unit = cross(d, arm);
        let sense = if dot(vp_unit, vg) >= 0.0 { 1.0 } else { -1.0 };
        let vp = mul(sense * zg / zp, vp_unit);
        let t = match tooth {
            Some(psi_g) => unit(add(mul(psi_g.cos(), gg), mul(psi_g.sin(), cross(n, gg)))),
            None => {
                let v12 = sub(vp, vg);
                if norm(v12) < 1e-12 * am {
                    return fail;
                }
                let t = unit(v12);
                if dot(t, gg) < 0.0 { mul(-1.0, t) } else { t }
            }
        };
        let spiral = |nn: V3, g: V3| {
            let tt = if dot(t, g) < 0.0 { mul(-1.0, t) } else { t };
            dot(tt, cross(nn, g)).atan2(dot(tt, g))
        };
        let psi_g = spiral(n, gg);
        let psi_p = spiral(mul(-1.0, n), gp);
        // A tooth line has no direction: measured modulo 180°, the error
        // runs on smoothly where the line turns square to the generator.
        let r2 = (hand * psi_p - self.spiral.to_radians() + PI / 2.0).rem_euclid(PI) - PI / 2.0;
        let rp = norm(cross(d, sub(p, apex)));
        let pinion_pitch = dot(unit(sub(p, apex)), d).clamp(-1.0, 1.0).acos();
        let xp = unit(sub(sub(p, apex), mul(dot(sub(p, apex), d), d)));
        let design = Design {
            spec: self.clone(),
            p,
            n,
            t,
            ring_pitch: gam,
            pinion_pitch,
            pinion_apex: apex,
            pinion_axis: d,
            pinion_x: xp,
            ring_spiral: psi_g,
            pinion_spiral: psi_p,
            ring_radius: rg,
            pinion_radius: rp,
            ring_cone: am,
            pinion_cone: norm(sub(p, apex)),
            sense,
            mn: 0.0,
            depth: 0.0,
            clearance: 0.0,
            ring_addendum: 0.0,
            pinion_addendum: 0.0,
            ring_dedendum: 0.0,
            pinion_dedendum: 0.0,
            ring_thickness: 0.0,
            ring_outer: self.ring_outer_radius() / gam.sin(),
            ring_inner: self.ring_outer_radius() / gam.sin() - self.face,
            cutter: Cutter {
                center: [0.0; 3],
                axis: [0.0; 3],
                x: [0.0; 3],
                radius: 0.0,
                width: 0.0,
                pitch_height: 0.0,
                alpha: 0.0,
                edge: 0.0,
            },
            slot_table: Vec::new(),
            floor: Vec::new(),
        };
        Trial { res: [r1, if tooth.is_some() { 0.0 } else { r2 }], design: Some(design) }
    }

    /// Solve the pitch cones for one hand of pinion.
    fn solve_hand(&self, hand: f64) -> Option<Design> {
        let g0 = self.bevel_cone();
        if self.offset.abs() < 1e-9 {
            // Spiral bevel: rolling cones; the ring's spiral angle is the
            // pinion's mirrored.
            let psi = self.spiral.to_radians();
            for psi_g in [psi, -psi] {
                let tr = self.trial(0.0, g0, hand, Some(psi_g));
                if let Some(d) = tr.design {
                    if (hand * d.pinion_spiral - psi).abs() < 1e-9 {
                        return Some(d);
                    }
                }
            }
            return None;
        }
        // Near a face gear (a bevel worm's wheel) each root has a mirror
        // image with the ring's cone turned inside out, past 90°: search,
        // and step, only below the steepest cone `proportions` takes.
        let steepest = MAX_RING_PITCH.to_radians();
        let f = |x: [f64; 2]| self.trial(x[0], x[1], hand, None).res;
        let newton = |mut x: [f64; 2]| -> Option<[f64; 2]> {
            for _ in 0..60 {
                let r = f(x);
                if r[0].abs() + r[1].abs() < 1e-13 {
                    break;
                }
                let h = 1e-7;
                let mut jac = [[0.0; 2]; 2];
                for k in 0..2 {
                    let mut xh = x;
                    xh[k] += h;
                    let rh = f(xh);
                    jac[0][k] = (rh[0] - r[0]) / h;
                    jac[1][k] = (rh[1] - r[1]) / h;
                }
                let det = jac[0][0] * jac[1][1] - jac[0][1] * jac[1][0];
                if det.abs() < 1e-300 {
                    return None;
                }
                let dx = [(r[0] * jac[1][1] - r[1] * jac[0][1]) / det, (jac[0][0] * r[1] - jac[1][0] * r[0]) / det];
                // Damp long steps.
                let k = (0.2 / (dx[0].abs() + dx[1].abs())).min(1.0);
                x = [x[0] - k * dx[0], (x[1] - k * dx[1]).min(steepest)];
            }
            Some(x)
        };
        // Polish the best points of a coarse search until one converges.
        let rg = self.ring_outer_radius();
        // A small offset leaves the root within a hair of the rolling cone,
        // where the spiral swings fast: look closely there too.
        let near = [-0.02, -0.01, -0.005, -0.002, -0.001, -0.0005, 0.0005, 0.001, 0.002, 0.005, 0.01, 0.02];
        let cones: Vec<f64> = (-8..=8).map(|j| 0.04 * j as f64).chain(near).map(|d| g0 + d).collect();
        let mut seeds: Vec<([f64; 2], f64)> = Vec::new();
        for i in -12..=16 {
            for &gam in &cones {
                let x = [(self.offset / rg).clamp(-0.9, 0.9) * (0.5 + 0.04 * i as f64), gam];
                if x[1] >= steepest {
                    continue;
                }
                let r = f(x);
                seeds.push((x, r[0] * r[0] + r[1] * r[1]));
            }
        }
        seeds.sort_by(|a, b| a.1.total_cmp(&b.1));
        seeds.iter().take(12).find_map(|&(x0, _)| {
            let x = newton(x0)?;
            let tr = self.trial(x[0], x[1], hand, None);
            (tr.res[0].abs() + tr.res[1].abs() < 1e-9 && x[1] < steepest).then_some(tr.design).flatten()
        })
    }

    /// Solve the pair: pitch cones, proportions and the ring's cutter.
    pub fn design(&self) -> Option<Design> {
        if self.pinion_teeth < 3 || self.ring_teeth < self.pinion_teeth || self.module <= 0.0 || self.face <= 0.0 {
            return None;
        }
        // The usual hand makes the pinion's spiral angle the larger; with
        // no offset, a left-hand pinion.
        let both: Vec<Design> = [1.0, -1.0].iter().filter_map(|&h| self.solve_hand(h)).collect();
        let usual = |d: &Design| {
            if self.offset.abs() < 1e-9 { pinion_left_hand(d) } else { d.pinion_spiral.abs() >= d.ring_spiral.abs() }
        };
        let pick = both.iter().find(|d| usual(d) != self.reverse_hand).or(both.first())?;
        let mut d = pick.clone();
        d.proportions()?;
        Some(d)
    }
}

/// Whether the pinion is left-handed: viewed from its apex, the outer half
/// of a tooth leans anticlockwise from the axial plane through its middle.
pub fn pinion_left_hand(d: &Design) -> bool {
    let radial = sub(d.p, d.pinion_apex);
    let g = unit(radial);
    let t = if dot(d.t, g) < 0.0 { mul(-1.0, d.t) } else { d.t };
    dot(t, cross(d.pinion_axis, radial)) < 0.0
}

pub fn ring_left_hand(d: &Design) -> bool {
    let g = unit(d.p);
    let t = if dot(d.t, g) < 0.0 { mul(-1.0, d.t) } else { d.t };
    dot(t, cross([0.0, 0.0, 1.0], d.p)) < 0.0
}

impl Design {
    fn proportions(&mut self) -> Option<()> {
        let alpha = self.spec.pressure_angle.to_radians();
        self.mn = 2.0 * self.ring_radius * self.ring_spiral.cos() / self.spec.ring_teeth as f64;
        let mn = self.mn;
        // The roots are rounded for the ball: deep enough that each root
        // fillet rises no higher than the mate's tips reach, by the true
        // corner of the ring's teeth (a little squarer than the pressure
        // angle makes it).
        // A ball too big to size the teeth for falls back on the usual
        // edge (and is reported by `ball_trouble`).
        let usual = 0.25 * mn;
        let want = if self.spec.ball > 0.0 { self.spec.ball / 2.0 } else { usual };
        [want, usual].into_iter().find_map(|want| {
            let mut clearance = usual.max(want * (1.0 - alpha.sin()) + 1e-3 * mn);
            for _ in 0..4 {
                self.size(clearance, want)?;
                let need = self.corner_rise() + 1e-3 * mn;
                if need <= clearance + 1e-9 {
                    break;
                }
                clearance = need;
            }
            Some(())
        })
    }

    /// How far up a ring tooth's flank the generating ring's rounded tip
    /// corner reaches, at worst across the face: the edge radius less its
    /// share along the face, by the angle between face and flank.
    fn corner_rise(&self) -> f64 {
        let blank = self.ring_blank();
        let pitch = TAU / self.spec.ring_teeth as f64;
        let re = self.cutter.edge;
        [self.ring_inner, (self.ring_inner + self.ring_outer) / 2.0, self.ring_outer]
            .iter()
            .map(|&s| {
                let t = blank.tip(s);
                let at = |phi: f64| section_point(blank.pitch, s, t, phi);
                // The tooth's edge on the face: from the slot's middle to
                // the tooth's.
                let slot = self.slot_azimuth(s.hypot(t));
                let (mut lo, mut hi) = (slot, slot + pitch / 2.0);
                for _ in 0..50 {
                    let m = (lo + hi) / 2.0;
                    if self.any_slot(at(m), 0.0) > 0.0 { lo = m } else { hi = m }
                }
                let x = at((lo + hi) / 2.0);
                let r = x[0].hypot(x[1]);
                let na = blank.face_normal();
                let n1 = [-na[0] * x[0] / r, -na[0] * x[1] / r, -na[1]];
                let h = 1e-5 * self.mn;
                let grad: V3 = std::array::from_fn(|k| {
                    let (mut a, mut b) = (x, x);
                    a[k] += h;
                    b[k] -= h;
                    (self.any_slot(b, 0.0) - self.any_slot(a, 0.0)) / (2.0 * h)
                });
                re * (1.0 - dot(n1, unit(grad)))
            })
            .fold(0.0, f64::max)
    }

    /// Proportions and the ring's cutter for clearance `clearance` and
    /// blade edge radius `want` (at most a full round).
    fn size(&mut self, clearance: f64, want: f64) -> Option<()> {
        let s = &self.spec;
        let (zp, zg) = (s.pinion_teeth as f64, s.ring_teeth as f64);
        let alpha = s.pressure_angle.to_radians();
        let mn = self.mn;
        self.depth = 2.0 * mn;
        self.clearance = clearance;
        let u = zg / zp;
        self.ring_addendum = self.depth * (0.21 + 0.29 / (u * u));
        self.pinion_addendum = self.depth - self.ring_addendum;
        self.ring_dedendum = self.pinion_addendum + self.clearance;
        self.pinion_dedendum = self.ring_addendum + self.clearance;
        self.ring_thickness = PI * mn / 2.0 - (self.pinion_addendum - self.ring_addendum) * alpha.tan();

        // Cutter: blade tips on the root plane at the mean point, set so
        // the slot runs along the tooth line there and its centre lies on
        // the apex side.
        let root = self.ring_root_angle();
        let eta = self.p[1].atan2(self.p[0]);
        let nr = [root.cos() * eta.cos(), root.cos() * eta.sin(), -root.sin()];
        let pr = sub(self.p, mul(self.ring_dedendum, nr));
        let gr = unit(pr);
        let mut tr = unit(sub(self.t, mul(dot(self.t, nr), nr)));
        if dot(tr, gr) < 0.0 {
            tr = mul(-1.0, tr);
        }
        let mut u_dir = cross(nr, tr);
        if dot(u_dir, gr) > 0.0 {
            u_dir = mul(-1.0, u_dir);
        }
        let rc = if s.cutter_radius > 0.0 { s.cutter_radius } else { (0.8 * self.ring_cone).round().max(1.0) };
        let center = add(pr, mul(rc, u_dir));
        let width = PI * mn - self.ring_thickness + s.backlash;
        let point_width = width - 2.0 * self.ring_dedendum * alpha.tan();
        if point_width <= 0.05 * mn || rc <= width {
            return None;
        }
        // The blade edge rounds the ring's slot bottom, a full round at
        // most; with no ball chosen, kept short of that.
        let full = point_width / 2.0 * alpha.cos() / (1.0 - alpha.sin());
        let edge = if s.ball > 0.0 {
            want.min(0.999 * full)
        } else {
            want.min(0.45 * point_width * (1.0 - alpha.sin()) / alpha.cos())
        };
        self.cutter = Cutter {
            center,
            axis: nr,
            x: mul(-1.0, u_dir),
            radius: rc,
            width,
            pitch_height: self.ring_dedendum,
            alpha,
            edge,
        };
        if self.ring_pitch >= MAX_RING_PITCH.to_radians() || self.pinion_pitch <= 1f64.to_radians() {
            return None;
        }
        let (lo, hi) = (self.ring_inner - 0.5 * s.face, self.ring_outer + 0.5 * s.face);
        let n = 96;
        self.slot_table = (0..=n).map(|i| lo + (hi - lo) * i as f64 / n as f64).map(|r| (r, self.slot_azimuth(r))).collect();
        Some(())
    }

    /// Face contact ratio: how far a tooth line advances round the ring
    /// across the face, in circular pitches at the mean point.
    pub fn face_contact_ratio(&self) -> f64 {
        self.spec.face * self.ring_spiral.abs().tan() / (TAU * self.ring_radius / self.spec.ring_teeth as f64)
    }

    /// Ring root angle (the cone the cutter's tip plane touches).
    pub fn ring_root_angle(&self) -> f64 {
        self.ring_pitch - (self.ring_dedendum / self.ring_cone).atan()
    }

    pub fn pinion_root_angle(&self) -> f64 {
        self.pinion_pitch - (self.pinion_dedendum / self.pinion_cone).atan()
    }

    /// Ring and pinion face cone angles: parallel to the mate's root.
    pub fn ring_face_angle(&self) -> f64 {
        self.ring_pitch + (self.pinion_dedendum / self.ring_cone).atan()
    }

    pub fn pinion_face_angle(&self) -> f64 {
        self.pinion_pitch + (self.ring_dedendum / self.pinion_cone).atan()
    }

    /// A pinion-frame point in the design frame.
    pub fn pinion_to_design(&self, q: V3) -> V3 {
        let y = cross(self.pinion_axis, self.pinion_x);
        add(self.pinion_apex, add(mul(q[0], self.pinion_x), add(mul(q[1], y), mul(q[2], self.pinion_axis))))
    }

    /// A design-frame point in the pinion's frame.
    pub fn design_to_pinion(&self, x: V3) -> V3 {
        let y = cross(self.pinion_axis, self.pinion_x);
        let w = sub(x, self.pinion_apex);
        [dot(w, self.pinion_x), dot(w, y), dot(w, self.pinion_axis)]
    }

    /// The ring's frame axes and origin expressed in the pinion's frame:
    /// for placing the ring relative to a placed pinion.
    pub fn ring_in_pinion(&self) -> (V3, V3, V3, V3) {
        let o = self.design_to_pinion([0.0; 3]);
        let turn = |v: V3| sub(self.design_to_pinion(v), o);
        (o, turn([1.0, 0.0, 0.0]), turn([0.0, 1.0, 0.0]), turn([0.0, 0.0, 1.0]))
    }
}

// ---- the cutting bodies -----------------------------------------------------

impl Cutter {
    /// How far inside the cutter's swept slot a point is (positive
    /// inside), with the slot floor raised by `floor`. Only the half of
    /// the cutter on the slot's side cuts.
    fn inside(&self, x: V3, floor: f64) -> f64 {
        let d = sub(x, self.center);
        let h = dot(d, self.axis);
        let radial = sub(d, mul(h, self.axis));
        let rho = norm(radial);
        if dot(radial, self.x) <= 0.0 {
            return -1e9;
        }
        let (sa, ca) = self.alpha.sin_cos();
        let ta = sa / ca;
        let re = self.edge;
        let half = self.width / 2.0;
        // Blade lines ρ = ci - h tan α (inner) and co + h tan α (outer),
        // offset inwards by the edge radius, and the floor raised by it.
        let ci = self.radius - half + self.pitch_height * ta + re / ca;
        let co = self.radius + half - self.pitch_height * ta - re / ca;
        let hb = floor + re;
        let s1 = h - hb;
        let s2 = (rho - ci) * ca + h * sa;
        let s3 = (co - rho) * ca + h * sa;
        if s1 >= 0.0 && s2 >= 0.0 && s3 >= 0.0 {
            return re + s1.min(s2).min(s3);
        }
        // Distance to the shrunk region: its bottom edge and two rays.
        let vin = [ci - hb * ta, hb];
        let vout = [co + hb * ta, hb];
        let q = [rho, h];
        let seg = |a: [f64; 2], b: [f64; 2]| {
            let ab = [b[0] - a[0], b[1] - a[1]];
            let l2 = ab[0] * ab[0] + ab[1] * ab[1];
            let k = if l2 > 0.0 { (((q[0] - a[0]) * ab[0] + (q[1] - a[1]) * ab[1]) / l2).clamp(0.0, 1.0) } else { 0.0 };
            (q[0] - a[0] - k * ab[0]).hypot(q[1] - a[1] - k * ab[1])
        };
        let ray = |a: [f64; 2], dir: [f64; 2]| {
            let k = ((q[0] - a[0]) * dir[0] + (q[1] - a[1]) * dir[1]).max(0.0);
            (q[0] - a[0] - k * dir[0]).hypot(q[1] - a[1] - k * dir[1])
        };
        let dist = seg(vin, vout).min(ray(vin, [-sa, ca])).min(ray(vout, [sa, ca]));
        re - dist
    }
}

/// A gear's blank in its own frame, by (r, z) half-plane tests.
#[derive(Clone, Copy, Debug)]
pub struct Blank {
    pub pitch: f64,
    /// Face cone: a point on it and its angle.
    pub face_point: [f64; 2],
    pub face_angle: f64,
    /// Cone distances of the toe and heel.
    pub inner: f64,
    pub outer: f64,
    /// A throated worm wheel's tip (its pitch cone flat, a cylinder): the
    /// torus round the worm's axis, as (centre distance, torus radius,
    /// height of the worm's axis). The face cone is then the rim.
    pub throat: Option<[f64; 3]>,
}

impl Blank {
    fn g(&self) -> [f64; 2] {
        [self.pitch.sin(), self.pitch.cos()]
    }

    /// Inside measure (positive inside) with the face raised by `lift`
    /// and the ends pushed out by `margin`.
    #[cfg(test)]
    fn inside(&self, rz: [f64; 2], lift: f64, margin: f64) -> f64 {
        self.below_face(rz, lift).min(self.within_ends(rz, margin))
    }

    /// Distance below the face cone raised by `lift`.
    fn below_face(&self, rz: [f64; 2], lift: f64) -> f64 {
        let na = self.face_normal();
        lift - ((rz[0] - self.face_point[0]) * na[0] + (rz[1] - self.face_point[1]) * na[1])
    }

    /// The face cone's outward normal in (r, z).
    fn face_normal(&self) -> [f64; 2] {
        [self.face_angle.cos(), -self.face_angle.sin()]
    }

    fn within_ends(&self, rz: [f64; 2], margin: f64) -> f64 {
        let g = self.g();
        let along = rz[0] * g[0] + rz[1] * g[1];
        (self.outer + margin - along).min(along - (self.inner - margin))
    }

    #[cfg(test)]
    pub fn inside_pub(&self, rz: [f64; 2]) -> f64 {
        self.inside(rz, 0.0, 0.0)
    }

    /// Depth of the face cone (or throat) on the section at cone distance s.
    pub fn tip(&self, s: f64) -> f64 {
        let (g, n) = ([self.pitch.sin(), self.pitch.cos()], [self.pitch.cos(), -self.pitch.sin()]);
        let na = [self.face_angle.cos(), -self.face_angle.sin()];
        let base = [s * g[0] - self.face_point[0], s * g[1] - self.face_point[1]];
        let rim = -(base[0] * na[0] + base[1] * na[1]) / (n[0] * na[0] + n[1] * na[1]);
        match self.throat {
            Some([a, rt, zw]) if (s - zw).abs() < rt => rim.min(a - (rt * rt - (s - zw) * (s - zw)).sqrt()),
            _ => rim,
        }
    }

    /// A radius to turn azimuths into lengths on the section at s: the
    /// pitch cone's, or on a cylinder (pitch angle 0), the tip's.
    pub fn arc_radius(&self, s: f64) -> f64 {
        let r = s * self.pitch.sin();
        if r > 1e-9 { r } else { self.face_point[0] }
    }

    /// The blank with its face cone and throat let in by `d`, for teeth
    /// eroded by `d`.
    pub fn eroded(&self, d: f64) -> Blank {
        let na = self.face_normal();
        Blank {
            face_point: [self.face_point[0] - d * na[0], self.face_point[1] - d * na[1]],
            throat: self.throat.map(|[a, rt, zw]| [a, rt + d, zw]),
            ..*self
        }
    }
}

/// Section point: cone distance s, depth t, azimuth φ, in a gear's frame.
pub fn section_point(pitch: f64, s: f64, t: f64, phi: f64) -> V3 {
    let r = s * pitch.sin() + t * pitch.cos();
    let z = s * pitch.cos() - t * pitch.sin();
    [r * phi.cos(), r * phi.sin(), z]
}

fn rot_z(a: f64, x: V3) -> V3 {
    let (s, c) = a.sin_cos();
    [x[0] * c - x[1] * s, x[0] * s + x[1] * c, x[2]]
}

impl Design {
    pub fn ring_blank(&self) -> Blank {
        let rz = [self.ring_radius, self.ring_cone * self.ring_pitch.cos()];
        let n = [self.ring_pitch.cos(), -self.ring_pitch.sin()];
        Blank {
            pitch: self.ring_pitch,
            face_point: [rz[0] + self.ring_addendum * n[0], rz[1] + self.ring_addendum * n[1]],
            face_angle: self.ring_face_angle(),
            inner: self.ring_inner,
            outer: self.ring_outer,
            throat: None,
        }
    }

    /// The pinion face runs a little past where the ring's teeth reach.
    pub fn pinion_blank(&self) -> Blank {
        let q = self.design_to_pinion(self.p);
        let rz = [q[0].hypot(q[1]), q[2]];
        let n = [self.pinion_pitch.cos(), -self.pinion_pitch.sin()];
        let c = &self.cutter;
        // The ring's mean tooth line: the cutter circle at pitch height.
        let y = cross(c.axis, c.x);
        let at = |b: f64| add(add(c.center, mul(c.pitch_height, c.axis)), mul(c.radius, add(mul(b.cos(), c.x), mul(b.sin(), y))));
        let cone = |b: f64| norm(at(b));
        let find = |target: f64| {
            // Walk from the mean point along the arc to the given cone distance.
            let mid = cone(0.0);
            let dir = if (cone(1e-3) - mid) * (target - mid) > 0.0 { 1.0 } else { -1.0 };
            let (mut lo, mut hi) = (0.0, dir * 1.5);
            for _ in 0..80 {
                let m = (lo + hi) / 2.0;
                if (cone(m) - target) * (mid - target) > 0.0 { lo = m } else { hi = m }
            }
            at((lo + hi) / 2.0)
        };
        let ends: Vec<f64> = [self.ring_inner, self.ring_outer]
            .iter()
            .map(|&s| {
                let x = self.design_to_pinion(find(s));
                let g = [self.pinion_pitch.sin(), self.pinion_pitch.cos()];
                x[0].hypot(x[1]) * g[0] + x[2] * g[1]
            })
            .collect();
        let (lo, hi) = (ends[0].min(ends[1]), ends[0].max(ends[1]));
        let pad = 0.04 * (hi - lo);
        Blank {
            pitch: self.pinion_pitch,
            face_point: [rz[0] + self.pinion_addendum * n[0], rz[1] + self.pinion_addendum * n[1]],
            face_angle: self.pinion_face_angle(),
            inner: lo - pad,
            outer: hi + pad,
            throat: None,
        }
    }

    /// How far inside slot `j`, as `cutter` cuts it, a ring-frame point
    /// is, the floor raised by `floor`.
    fn slot(&self, cutter: &Cutter, x: V3, j: i32, floor: f64) -> f64 {
        let pitch = TAU / self.spec.ring_teeth as f64;
        cutter.inside(rot_z(-(j as f64) * pitch, x), floor)
    }

    /// Azimuth of slot 0's middle at distance ρ from the apex: where the
    /// cutter circle at pitch height reaches that far.
    fn slot_azimuth(&self, rho: f64) -> f64 {
        let c = &self.cutter;
        let y = cross(c.axis, c.x);
        let base = add(c.center, mul(c.pitch_height, c.axis));
        let at = |b: f64| add(base, mul(c.radius, add(mul(b.cos(), c.x), mul(b.sin(), y))));
        // |at(b)| grows monotonically one way from b = 0 over the face.
        let up = norm(at(1e-3)) > norm(at(0.0));
        let (mut lo, mut hi) = if up { (-1.2, 1.2) } else { (1.2, -1.2) };
        for _ in 0..50 {
            let m = (lo + hi) / 2.0;
            if norm(at(m)) < rho { lo = m } else { hi = m }
        }
        let p = at((lo + hi) / 2.0);
        p[1].atan2(p[0])
    }

    /// How far the slot floors are raised at cone distance `rho`: a
    /// Catmull-Rom spline through `floor`, level past the ends.
    pub fn floor_at(&self, rho: f64) -> f64 {
        let n = self.floor.len();
        if n < 2 {
            return 0.0;
        }
        let k = ((rho - self.ring_inner) / (self.ring_outer - self.ring_inner) * (n - 1) as f64).clamp(0.0, (n - 1) as f64);
        let i = (k.floor() as usize).min(n - 2);
        let t = k - i as f64;
        let at = |j: isize| self.floor[j.clamp(0, n as isize - 1) as usize];
        let [p0, p1, p2, p3] = [at(i as isize - 1), at(i as isize), at(i as isize + 1), at(i as isize + 2)];
        let v = 0.5
            * (2.0 * p1 + (p2 - p0) * t + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * t * t + (3.0 * p1 - p0 - 3.0 * p2 + p3) * t * t * t);
        v.max(0.0)
    }

    /// Inside measure of any slot near a ring-frame point.
    pub(crate) fn any_slot(&self, x: V3, floor: f64) -> f64 {
        self.any_slot_by(&self.cutter, x, floor)
    }

    fn any_slot_by(&self, cutter: &Cutter, x: V3, floor: f64) -> f64 {
        let pitch = TAU / self.spec.ring_teeth as f64;
        let rho = norm(x);
        let floor = floor + self.floor_at(rho);
        let az = self.slot_table.iter().rev().find(|e| e.0 <= rho).or(self.slot_table.first()).map_or(0.0, |e| e.1);
        let rel = x[1].atan2(x[0]) - az;
        let j0 = (rel.rem_euclid(TAU) / pitch).round() as i32;
        (-1..=1).map(|k| self.slot(cutter, x, j0 + k, floor)).fold(f64::MIN, f64::max)
    }

    /// The generating ring gear (tip and floor raised by the clearance,
    /// ends extended): inside measure, positive in its material. Its tip
    /// corners are rounded by the blade edge radius, so the pinion's root
    /// fillets it cuts are no tighter than the ball. Its raised slot floor
    /// meets the flanks square: the clearance keeps the real ring's root
    /// fillets below the pinion's tips, so they shape nothing.
    fn tool(&self, blank: &Blank, x: V3) -> f64 {
        let r = x[0].hypot(x[1]);
        let rz = [r, x[2]];
        let c = self.clearance;
        let ends = blank.within_ends(rz, 0.3 * self.spec.face);
        let face = blank.below_face(rz, c);
        let sharp = Cutter { edge: 0.0, ..self.cutter };
        let slot = |x: V3| self.any_slot_by(&sharp, x, c);
        let side = -slot(x);
        let re = self.cutter.edge;
        if face >= re || side >= re || re <= 0.0 || r < 1e-9 {
            return face.min(side).min(ends);
        }
        // The rounded corner: re less the distance to the edge where the
        // surfaces, both pulled in by re, meet. The cosine between their
        // inward normals: the face cone's from its meridian, the flank's
        // by a difference.
        let na = blank.face_normal();
        let n1 = [-na[0] * x[0] / r, -na[0] * x[1] / r, -na[1]];
        let h = 1e-4 * self.mn;
        let grad: V3 = std::array::from_fn(|k| {
            let mut xh = x;
            xh[k] += h;
            (-slot(xh) - side) / h
        });
        let cos = dot(n1, unit(grad)).clamp(-0.99, 0.99);
        let (u, v) = (re - face, re - side);
        let s2 = 1.0 - cos * cos;
        let (l1, l2) = ((u - v * cos) / s2, (v - u * cos) / s2);
        let corner = if l1 > 0.0 && l2 > 0.0 { re - (l1 * l1 + l2 * l2 + 2.0 * l1 * l2 * cos).sqrt() } else { face.min(side) };
        corner.min(ends)
    }

    /// The generating ring's tooth across its raised tip at the toe,
    /// square to the tooth (where it is narrowest): the most room it has
    /// to round its corners.
    pub fn tool_tip_width(&self) -> f64 {
        let blank = self.ring_blank();
        let s = self.ring_inner;
        let pitch = TAU / self.spec.ring_teeth as f64;
        let t = blank.tip(s) + self.clearance;
        let inside = |phi: f64| self.any_slot(section_point(blank.pitch, s, t, phi), self.clearance);
        let n = 96;
        let mut width = 0.0;
        for i in 0..n {
            let (a, b) = (pitch * i as f64 / n as f64, pitch * (i + 1) as f64 / n as f64);
            let (fa, fb) = (inside(a), inside(b));
            if fa < 0.0 && fb < 0.0 {
                width += b - a;
            } else if (fa < 0.0) != (fb < 0.0) {
                let (mut lo, mut hi) = (a, b);
                for _ in 0..40 {
                    let m = (lo + hi) / 2.0;
                    if (inside(m) < 0.0) == (fa < 0.0) { lo = m } else { hi = m }
                }
                width += if fa < 0.0 { lo - a } else { b - lo };
            }
        }
        let radius = s * blank.pitch.sin() + t * blank.pitch.cos();
        width * radius * self.ring_spiral.cos()
    }

    /// Why the ball end mill can't cut this pair, if it can't.
    pub fn ball_trouble(&self) -> Option<&'static str> {
        let rb = self.spec.ball / 2.0;
        if rb <= 0.0 {
            return None;
        }
        if self.cutter.edge < rb - 1e-9 {
            return Some("the ring gear's slots are narrower than it at the bottom");
        }
        let (sa, ca) = self.cutter.alpha.sin_cos();
        if self.tool_tip_width() < 2.0 * rb * (1.0 - sa) / ca {
            return Some("the pinion's spaces are narrower than it at the bottom, at the toe");
        }
        None
    }
}

// ---- tooth sections ---------------------------------------------------------

/// One gear of the set: tooth 0's two flanks on each section, from the
/// slot bottom (where the flanks of neighbouring teeth meet) to the tip.
#[derive(Clone, Debug)]
pub struct Member {
    pub teeth: u32,
    pub blank: Blank,
    /// Cone distances of the sections, toe to heel.
    pub stations: Vec<f64>,
    pub t_root: Vec<f64>,
    pub t_tip: Vec<f64>,
    /// Per section, (t, φ) up each flank: `right` bounds the tooth on its
    /// low-azimuth side, `left` on its high side. Index 0 is the slot
    /// bottom: right[k][0] is slot 0's, left[k][0] slot 1's (one pitch on).
    pub right: Vec<Vec<[f64; 2]>>,
    pub left: Vec<Vec<[f64; 2]>>,
    /// Depth of the hub circle on the toe and heel sections, where the end
    /// cones meet the flat faces.
    pub hub: [f64; 2],
    pub bore: f64,
    /// How far the ring's slot floors were raised for the ball end mill's
    /// reach, and the pinion's tips cut down with them, at most.
    pub raised: f64,
}

impl Member {
    pub fn pitch(&self) -> f64 {
        TAU / self.teeth as f64
    }

    pub fn point(&self, s: f64, t: f64, phi: f64) -> V3 {
        section_point(self.blank.pitch, s, t, phi)
    }

    /// Millimetres per radian of azimuth on section k, for laying its end
    /// face out flat: the pitch radius there, or on a cylinder the middle
    /// of the teeth.
    pub fn arc_scale(&self, k: usize) -> f64 {
        let r = self.stations[k] * self.blank.pitch.sin();
        if r > 1e-9 { r } else { (self.t_root[k] + self.t_tip[k]) / 2.0 }
    }

    /// Heights of the toe and heel flat faces, and their radii.
    pub fn hub_faces(&self) -> [(f64, f64); 2] {
        let k = self.stations.len() - 1;
        [0, 1].map(|e| {
            let s = if e == 0 { self.stations[0] } else { self.stations[k] };
            let p = self.point(s, self.hub[e], 0.0);
            (p[2], p[0])
        })
    }

    /// Flank points of tooth `tooth` in 3D: [section][profile index].
    pub fn flank(&self, left: bool, tooth: usize) -> Vec<Vec<V3>> {
        let rot = tooth as f64 * self.pitch();
        let side = if left { &self.left } else { &self.right };
        side.iter()
            .zip(&self.stations)
            .map(|(prof, &s)| prof.iter().map(|&[t, phi]| self.point(s, t, phi + rot)).collect())
            .collect()
    }
}

/// Points per flank on each section, and sections across the face.
pub const PROFILE_POINTS: usize = 32;
pub const SECTIONS: usize = 11;

/// What a gear's `sections` sections are solved from: `gap(s, t, φ)` is
/// positive in the tooth space and negative in the tooth.
pub(crate) fn build_member(
    teeth: u32,
    blank: Blank,
    bore: f64,
    hub: [f64; 2],
    sections: usize,
    gap: &(dyn Fn(f64, f64, f64) -> f64 + Sync),
) -> Result<Member, String> {
    let pitch = TAU / teeth as f64;
    let stations: Vec<f64> =
        (0..sections).map(|k| blank.inner + (blank.outer - blank.inner) * k as f64 / (sections - 1) as f64).collect();
    let results: Vec<Result<(f64, f64, Vec<[f64; 2]>, Vec<[f64; 2]>), String>> = std::thread::scope(|scope| {
        let handles: Vec<_> = stations.iter().map(|&s| scope.spawn(move || section(s, pitch, &blank, gap))).collect();
        handles.into_iter().map(|h| h.join().unwrap_or(Err("section failed".into()))).collect()
    });
    let mut m = Member {
        teeth,
        blank,
        stations: stations.clone(),
        t_root: vec![],
        t_tip: vec![],
        right: vec![],
        left: vec![],
        hub: [0.0; 2],
        bore,
        raised: 0.0,
    };
    for r in results {
        let (tr, tt, right, left) = r?;
        m.t_root.push(tr);
        m.t_tip.push(tt);
        m.right.push(right);
        m.left.push(left);
    }
    // Each section finds its own slot, which can be a pitch away from its
    // neighbour's: shift sections by whole pitches so tooth 0 runs
    // continuously across the face, anchored on the middle section.
    let mid = sections / 2;
    let centre = |m: &Member, k: usize| m.right[k][PROFILE_POINTS / 2][1];
    for order in [(mid + 1..sections).collect::<Vec<_>>(), (0..mid).rev().collect()] {
        for k in order {
            let prev = if k > mid { k - 1 } else { k + 1 };
            let shift = ((centre(&m, prev) - centre(&m, k)) / pitch).round() * pitch;
            if shift != 0.0 {
                for q in m.right[k].iter_mut().chain(m.left[k].iter_mut()) {
                    q[1] += shift;
                }
            }
        }
    }
    let k = sections - 1;
    m.hub = [m.t_root[0] - hub[0], m.t_root[k] - hub[1]];
    Ok(m)
}

/// Lower a face cone until the generating body no longer reaches the tooth
/// tops anywhere along the face (its raised root sets the clearance),
/// leaving a top land at least `land` wide.
fn clear_tips(mut blank: Blank, pitch: f64, land: f64, gap: &(dyn Fn(f64, f64, f64) -> f64 + Sync)) -> Blank {
    for _ in 0..3 {
        let b = blank;
        let overlap = |k: usize| {
            let s = b.inner + (b.outer - b.inner) * k as f64 / (SECTIONS - 1) as f64;
            let tip = b.tip(s);
            // Middle of the tooth at the tip: the scan's deepest material.
            let n = 48;
            let mid = (0..n)
                .map(|i| pitch * i as f64 / n as f64)
                .min_by(|x, y| gap(s, tip, *x).total_cmp(&gap(s, tip, *y)))
                .unwrap_or(0.0);
            // The land across the middle, as an azimuth at this depth.
            let half = |t: f64| land / 2.0 / (s * b.pitch.sin() + t * b.pitch.cos());
            let touched = |t: f64| (-2..=2).any(|i| gap(s, t, mid + half(t) * i as f64 / 2.0) >= 0.0);
            if !touched(tip) {
                return 0.0;
            }
            let (mut lo, mut hi) = (0.0, tip);
            for _ in 0..30 {
                let m = (lo + hi) / 2.0;
                if touched(m) { hi = m } else { lo = m }
            }
            tip - lo
        };
        let worst = std::thread::scope(|scope| {
            let hs: Vec<_> = (0..SECTIONS).map(|k| scope.spawn(move || overlap(k))).collect();
            hs.into_iter().map(|h| h.join().unwrap_or(0.0)).fold(0.0, f64::max)
        });
        if worst <= 0.0 {
            break;
        }
        let n = [blank.pitch.cos(), -blank.pitch.sin()];
        let drop = worst * 1.02 + 1e-4;
        blank.face_point = [blank.face_point[0] - drop * n[0], blank.face_point[1] - drop * n[1]];
    }
    blank
}

/// Maximise f on [a, b] by golden section.
pub(crate) fn golden(f: &dyn Fn(f64) -> f64, mut a: f64, mut b: f64, iters: usize) -> (f64, f64) {
    let k = 0.5 * (5f64.sqrt() - 1.0);
    let (mut c, mut d) = (b - k * (b - a), a + k * (b - a));
    let (mut fc, mut fd) = (f(c), f(d));
    for _ in 0..iters {
        if fc > fd {
            b = d;
            d = c;
            fd = fc;
            c = b - k * (b - a);
            fc = f(c);
        } else {
            a = c;
            c = d;
            fc = fd;
            d = a + k * (b - a);
            fd = f(d);
        }
    }
    if fc > fd { (c, fc) } else { (d, fd) }
}

/// Root of f between a and b (f(a), f(b) of opposite signs): Illinois.
fn root(f: &dyn Fn(f64) -> f64, mut a: f64, mut b: f64) -> f64 {
    let (mut fa, mut fb) = (f(a), f(b));
    if fa == 0.0 {
        return a;
    }
    if (fa > 0.0) == (fb > 0.0) {
        return if fa.abs() < fb.abs() { a } else { b };
    }
    let mut side = 0;
    for _ in 0..100 {
        let mut c = (a * fb - b * fa) / (fb - fa);
        if !(c > a.min(b) && c < a.max(b)) {
            c = (a + b) / 2.0;
        }
        let fc = f(c);
        if fc == 0.0 || (b - a).abs() < 1e-13 {
            return c;
        }
        if (fc > 0.0) == (fb > 0.0) {
            b = c;
            fb = fc;
            if side == -1 {
                fa /= 2.0;
            }
            side = -1;
        } else {
            a = c;
            fa = fc;
            if side == 1 {
                fb /= 2.0;
            }
            side = 1;
        }
        if (b - a).abs() < 1e-12 {
            break;
        }
    }
    (a + b) / 2.0
}

/// One section: root depth, tip depth, and both flanks resampled evenly
/// along their length.
///
/// Each flank is traced as the contour gap = 0 in the section, from the
/// tooth tip down through the fillet and along the floor of the space to
/// its deepest point, the seam shared with the neighbouring tooth. Tracing
/// by arc length copes with the floor, where the contour runs nearly
/// level and solving for azimuth at a given depth would be ill-posed.
#[allow(clippy::type_complexity)]
fn section(
    s: f64,
    pitch: f64,
    blank: &Blank,
    gap: &(dyn Fn(f64, f64, f64) -> f64 + Sync),
) -> Result<(f64, f64, Vec<[f64; 2]>, Vec<[f64; 2]>), String> {
    let t_tip = blank.tip(s);
    // Work in (depth, arc along the pitch circle) so both axes are mm.
    let rs = blank.arc_radius(s);
    let f = |p: [f64; 2]| gap(s, p[0], p[1] / rs);
    let scale = pitch * rs;
    // Tooth and space middles at the tip, from a scan round one pitch.
    let n = 96;
    let tip_row: Vec<(f64, f64)> = (0..n)
        .map(|i| pitch * i as f64 / n as f64)
        .map(|phi| (phi, gap(s, t_tip, phi)))
        .collect();
    let (tooth, tv) = tip_row.iter().copied().min_by(|a, b| a.1.total_cmp(&b.1)).unwrap();
    if tv >= 0.0 {
        return Err("teeth come to a point below the tip".into());
    }
    let tooth = golden(&|phi| -gap(s, t_tip, phi), tooth - pitch / n as f64, tooth + pitch / n as f64, 40).0;
    let fr = |phi: f64| gap(s, t_tip, phi);
    // Walking down from the tooth middle each way, the first opening.
    let open = |dir: f64| {
        let mut a = tooth;
        for i in 1..=n {
            let b = tooth + dir * pitch * i as f64 / n as f64;
            if fr(b) > 0.0 {
                return Some(root(&fr, a, b));
            }
            a = b;
        }
        None
    };
    let (Some(r_tip), Some(l_tip)) = (open(-1.0), open(1.0)) else {
        return Err("no tooth space at the tip".into());
    };

    let grad = |p: [f64; 2]| {
        let e = 1e-6 * scale;
        [
            (f([p[0] + e, p[1]]) - f([p[0] - e, p[1]])) / (2.0 * e),
            (f([p[0], p[1] + e]) - f([p[0], p[1] - e])) / (2.0 * e),
        ]
    };
    // Back onto the contour along the gradient (taken once: the step is
    // short, so it barely changes).
    let settle = |mut p: [f64; 2]| {
        let g = grad(p);
        let g2 = g[0] * g[0] + g[1] * g[1];
        if g2 <= 0.0 {
            return p;
        }
        for _ in 0..8 {
            let v = f(p);
            if v.abs() < 1e-10 {
                break;
            }
            p = [p[0] - v * g[0] / g2, p[1] - v * g[1] / g2];
        }
        p
    };
    // The seam goes down the middle of the space: halfway between the
    // flanks at the tip, so it runs smoothly from section to section
    // (the floor's deepest point can wander from one side to the other).
    let centre = (r_tip + l_tip - pitch) / 2.0 * rs;
    // Trace from a tip point down and along the floor until past the
    // space's middle (`past` says when).
    let trace = |start: [f64; 2], past: &dyn Fn(f64) -> bool| -> Result<Vec<[f64; 2]>, String> {
        let h = scale / 110.0;
        let mut pts = vec![start];
        // Keep the space on the same side throughout, starting down into
        // the space: unlike following on from the last step, this carries
        // the trace over a crease, such as a ridge the cutter's passes
        // leave on the floor.
        let mut side = 0.0;
        for _ in 0..2000 {
            let p = *pts.last().unwrap();
            let g = grad(p);
            let gl = g[0].hypot(g[1]);
            if gl <= 0.0 {
                return Err("flank trace lost".into());
            }
            if side == 0.0 {
                side = if g[1] > 0.0 { 1.0 } else { -1.0 };
            }
            let tau = [-side * g[1] / gl, side * g[0] / gl];
            if past(p[1]) && pts.len() > 1 {
                return Ok(pts);
            }
            // The next contour point a step away: sweeping round from
            // straight into the space towards the material, the first
            // crossing. Unlike stepping ahead and settling back, this goes
            // over the tip of a ridge, however sharp.
            let at = |beta: f64| {
                let (sb, cb) = (side * beta).sin_cos();
                let d = [(g[0] * cb - g[1] * sb) / gl, (g[0] * sb + g[1] * cb) / gl];
                [p[0] + h * d[0], p[1] + h * d[1]]
            };
            let sweep = 36;
            let crossing = (1..=sweep).map(|k| PI * k as f64 / sweep as f64).find(|&b| f(at(b)) <= 0.0);
            let q = match crossing {
                Some(b) if f(at(b - PI / sweep as f64)) > 0.0 => {
                    at(root(&|beta| f(at(beta)), b - PI / sweep as f64, b))
                }
                _ => settle([p[0] + h * tau[0], p[1] + h * tau[1]]),
            };
            pts.push(q);
        }
        Err("flank trace did not reach the floor".into())
    };
    let mut right = trace([t_tip, r_tip * rs], &|v| v <= centre)?;
    let mut left = trace([t_tip, l_tip * rs], &|v| v >= centre + pitch * rs)?;
    // The seam: where the middle of the space meets the floor.
    let last = *right.last().unwrap();
    let down = |t: f64| f([t, centre]);
    let (mut lo, hi) = (last[0] - scale / 30.0, t_tip);
    for _ in 0..6 {
        if down(lo) < 0.0 {
            break;
        }
        lo -= scale / 10.0;
    }
    if down(lo) >= 0.0 || down(hi) <= 0.0 {
        return Err("tooth space floor not found".into());
    }
    let t_root = root(&down, lo, hi);
    let seam = [t_root, centre];
    // Drop trace points past the middle; the seam ends both flanks.
    right.retain(|p| p[1] > centre);
    left.retain(|p| p[1] < centre + pitch * rs);
    right.push(seam);
    left.push([t_root, centre + pitch * rs]);
    // Seam to tip, evenly spaced along the contour.
    let resample = |trace: &[[f64; 2]], seam: [f64; 2]| -> Vec<[f64; 2]> {
        let mut prof: Vec<[f64; 2]> = trace.iter().rev().copied().collect();
        prof[0] = seam;
        let pts: Vec<V3> = prof.iter().map(|&[t, v]| section_point(blank.pitch, s, t, v / rs)).collect();
        let mut acc = vec![0.0];
        for w in pts.windows(2) {
            acc.push(acc.last().unwrap() + norm(sub(w[1], w[0])));
        }
        let total = *acc.last().unwrap();
        (0..=PROFILE_POINTS)
            .map(|i| {
                if i == 0 || i == PROFILE_POINTS {
                    let p = if i == 0 { seam } else { *prof.last().unwrap() };
                    return [p[0], p[1] / rs];
                }
                let target = total * i as f64 / PROFILE_POINTS as f64;
                let k = acc.partition_point(|&a| a < target).clamp(1, acc.len() - 1);
                let w = (target - acc[k - 1]) / (acc[k] - acc[k - 1]).max(1e-300);
                let p = [prof[k - 1][0] + w * (prof[k][0] - prof[k - 1][0]), prof[k - 1][1] + w * (prof[k][1] - prof[k - 1][1])];
                // Between two trace points a short step apart, p is all
                // but on the contour already: keep it if settling it goes
                // astray, as it can off a crease, where the gradient fails.
                let q = settle(p);
                let moved = (q[0] - p[0]).hypot(q[1] - p[1]);
                let p = if moved < scale / 110.0 && f(q).abs() <= f(p).abs() { q } else { p };
                [p[0], p[1] / rs]
            })
            .collect()
    };
    let r = resample(&right, seam);
    let mut l = resample(&left, [seam[0], seam[1] + pitch * rs]);
    // Exactly one pitch apart at the seam.
    l[0] = [t_root, seam[1] / rs + pitch];
    Ok((t_root, t_tip, r, l))
}

impl Design {
    /// The pinion and ring gear as the ball end mill can cut them on the
    /// 4-axis mill (see `reachable`).
    pub fn members(&self) -> Result<(Member, Member), String> {
        let d = self.reachable()?;
        let raised = d.floor.iter().copied().fold(0.0, f64::max);
        let (mut pinion, mut ring) = (d.pinion()?, d.ring()?);
        (pinion.raised, ring.raised) = (raised, raised);
        Ok((pinion, ring))
    }

    /// The design as the ball end mill can cut it on the 4-axis mill. A
    /// tool kept square to the ring's axis can't follow its curved slots
    /// all the way down, near the toe most: there the slot floors are
    /// raised until it can. The pinion's tips, cut by the ring's slots,
    /// come down with them and keep their clearance; the flanks above are
    /// as designed, the contact a little shorter.
    pub fn reachable(&self) -> Result<Design, String> {
        let mut d = self.clone();
        d.raise_floors()?;
        Ok(d)
    }

    /// Raise the ring's slot floors, a step at a time where the ball end
    /// mill can't reach, up to half the working depth.
    fn raise_floors(&mut self) -> Result<(), String> {
        const KNOTS: usize = 9;
        let ball = self.spec.ball;
        if ball <= 0.0 {
            return Ok(());
        }
        self.floor = vec![0.0; KNOTS];
        let (step, most) = (0.08 * self.depth, 0.5 * self.depth);
        for _ in 0..12 {
            let ring = self.ring()?;
            let r = reach::check(&reach::member(&ring, ball), ball);
            if r.share() <= reach::STRAY {
                break;
            }
            let span = self.ring_outer - self.ring_inner;
            let mut up = [false; KNOTS];
            for p in &r.missed {
                let k = (norm(*p) - self.ring_inner) / span * (KNOTS - 1) as f64;
                for (i, u) in up.iter_mut().enumerate() {
                    *u |= (i as f64 - k).abs() <= 1.5;
                }
            }
            let mut moved = false;
            for (f, u) in self.floor.iter_mut().zip(up) {
                if u && *f < most {
                    *f = (*f + step).min(most);
                    moved = true;
                }
            }
            if !moved {
                break;
            }
        }
        Ok(())
    }

    /// The ring gear's sections: slots straight from the cutter.
    pub fn ring(&self) -> Result<Member, String> {
        let blank = self.ring_blank();
        // For the 3D printer the teeth are eroded by a quarter of the nozzle width:
        // the slots that much wider and deeper, the face that much lower.
        let d = self.spec.nozzle / 4.0;
        let gap = |s: f64, t: f64, phi: f64| self.any_slot(section_point(blank.pitch, s, t, phi), 0.0) + d;
        let h = self.depth;
        let mut m = build_member(self.spec.ring_teeth, blank.eroded(d), self.spec.ring_bore, [1.5 * h, 0.5 * h], SECTIONS, &gap)?;
        // Near a face gear the toe and heel faces come level, or cross:
        // keep the back (heel) face at least half a tooth depth behind the
        // front.
        let [(z_toe, _), (z_heel, _)] = m.hub_faces();
        let short = z_toe + 0.5 * h - z_heel;
        if short > 0.0 {
            m.hub[1] -= short / m.blank.pitch.sin();
        }
        Ok(m)
    }

    /// The pinion's sections: cut by the rolling ring gear.
    pub fn pinion(&self) -> Result<Member, String> {
        let blank = self.pinion_blank();
        let ring = self.ring_blank();
        let (zp, zg) = (self.spec.pinion_teeth as f64, self.spec.ring_teeth as f64);
        let k = self.sense * zg / zp;
        // Positive where some position of the generating ring has
        // material: the max of its inside measure over the ring positions
        // while this point passes through mesh (its pinion azimuth within
        // 60° of the mean point's, which sits at azimuth 0).
        let reach = (PI / 3.0) / k.abs();
        // For the 3D printer the teeth are eroded by a quarter of the nozzle width:
        // the generating ring is that much fatter, the face that much lower.
        let d = self.spec.nozzle / 4.0;
        let gap = |s: f64, t: f64, phi: f64| {
            let q = section_point(blank.pitch, s, t, phi);
            let r = q[0].hypot(q[1]);
            let at = |theta: f64| {
                let qa = phi + k * theta;
                let x = self.pinion_to_design([r * qa.cos(), r * qa.sin(), q[2]]);
                self.tool(&ring, rot_z(-theta, x))
            };
            // Centre the window on when this point passes the mean point.
            let wrapped = (phi + PI).rem_euclid(TAU) - PI;
            let centre = -wrapped / k;
            let n = 40;
            let step = 2.0 * reach / n as f64;
            let mut samples: Vec<(f64, f64)> =
                (0..=n).map(|i| centre - reach + step * i as f64).map(|th| (th, at(th))).collect();
            samples.sort_by(|a, b| b.1.total_cmp(&a.1));
            samples
                .iter()
                .take(3)
                .map(|&(th, _)| golden(&at, th - step, th + step, 30).1)
                .fold(f64::MIN, f64::max)
                + d
        };
        let h = self.depth;
        // The usual least top land for bevel gears: a quarter module.
        let blank = clear_tips(blank.eroded(d), TAU / zp, 0.25 * self.spec.module, &gap);
        let mut m = build_member(self.spec.pinion_teeth, blank, self.spec.pinion_bore, [0.5 * h, 0.5 * h], SECTIONS, &gap)?;
        // A slender pinion (a bevel worm's) has little below its roots:
        // keep the hub circles clear of the bore and off the axis.
        let (sg, cg) = m.blank.pitch.sin_cos();
        let rb = self.spec.pinion_bore / 2.0;
        for (e, k) in [(0, 0), (1, m.stations.len() - 1)] {
            let s = m.stations[k];
            let root = s * sg + m.t_root[k] * cg;
            if root < 0.1 * h {
                return Err("The pinion's roots reach its axis at the toe: narrow the face or steepen the spiral.".into());
            }
            let wall = if rb > 0.0 { rb + 0.25 * h } else { 0.0 };
            let r = (s * sg + m.hub[e] * cg).max(wall).max(0.5 * root);
            if r > root - 0.05 * h {
                return Err("The bore is too big for the pinion: make it smaller.".into());
            }
            m.hub[e] = (r - s * sg) / cg;
        }
        Ok(m)
    }
}

#[cfg(test)]
pub mod tests {
    use super::*;

    pub fn car() -> Spec {
        Spec {
            pinion_teeth: 11,
            ring_teeth: 41,
            module: 5.0,
            pressure_angle: 20.0,
            face: 32.0,
            offset: 30.0,
            shaft_angle: 90.0,
            spiral: 45.0,
            reverse_hand: false,
            cutter_radius: 0.0,
            backlash: 0.0,
            pinion_bore: 15.0,
            ring_bore: 110.0,
            nozzle: 0.0,
            ball: 0.0,
        }
    }

    #[test]
    fn pitch_cones_touch_and_teeth_share_a_normal_pitch() {
        for offset in [0.0, 15.0, 30.0, -30.0] {
            let d = Spec { offset, ..car() }.design().expect("design");
            // Tangent cones: the normal lies in both meridian planes.
            let m = cross(d.pinion_axis, sub(d.p, d.pinion_apex));
            assert!(dot(d.n, unit(m)).abs() < 1e-9, "offset {offset}");
            assert!((dot(d.n, unit(d.p))).abs() < 1e-12);
            // Equal normal pitch on both gears at the mean point.
            let pg = TAU * d.ring_radius * d.ring_spiral.cos() / 41.0;
            let pp = TAU * d.pinion_radius * d.pinion_spiral.cos() / 11.0;
            assert!((pg - pp).abs() < 1e-9 * pg, "offset {offset}: {pg} {pp}");
            assert!((d.pinion_spiral.abs() - 45f64.to_radians()).abs() < 1e-9);
            // Pinion axis at the right offset.
            let (l0, dir) = Spec { offset, ..car() }.offset_line();
            assert!(norm(cross(dir, sub(d.pinion_apex, l0))) < 1e-9);
            println!(
                "E {offset}: Γ {:.3}° γ {:.3}° ψg {:.3}° ψp {:.3}° rp {:.3} rg {:.3} pinion {}",
                d.ring_pitch.to_degrees(),
                d.pinion_pitch.to_degrees(),
                d.ring_spiral.to_degrees(),
                d.pinion_spiral.to_degrees(),
                d.pinion_radius,
                d.ring_radius,
                if pinion_left_hand(&d) { "LH" } else { "RH" }
            );
        }
    }

    #[test]
    fn usual_car_set_has_a_left_hand_pinion_enlarged_by_the_offset() {
        let d = car().design().unwrap();
        assert!(pinion_left_hand(&d));
        assert!(!ring_left_hand(&d));
        assert!(d.pinion_spiral.abs() > d.ring_spiral.abs());
        let bevel = Spec { offset: 0.0, ..car() }.design().unwrap();
        assert!(d.pinion_radius > bevel.pinion_radius);
    }

    #[test]
    fn ring_slot_matches_the_cutter() {
        let d = car().design().unwrap();
        let c = d.cutter;
        // On the pitch line at the mean point, the slot is the cutter's
        // width wide, centred on the cutter circle.
        let mid = add(add(c.center, mul(c.pitch_height, c.axis)), mul(c.radius, c.x));
        assert!(c.inside(mid, 0.0) > 0.0);
        let edge = add(mid, mul(c.width / 2.0 - 1e-6, c.x));
        let out = add(mid, mul(c.width / 2.0 + 1e-6, c.x));
        assert!(c.inside(edge, 0.0) > 0.0 && c.inside(out, 0.0) < 0.0);
        // The mean point of the pitch cone lies in the slot's middle.
        assert!(norm(sub(mid, d.p)) < 1e-9);
    }

    /// Turn the pair through one ring pitch: at each step, how deep the
    /// pinion's flanks reach into the ring gear (negative: clear of it).
    fn deepest_through_mesh(d: &Design) -> Vec<f64> {
        let pinion = d.pinion().unwrap();
        let ring = d.ring_blank();
        let (zp, zg) = (d.spec.pinion_teeth, d.spec.ring_teeth as f64);
        let k = d.sense * zg / zp as f64;
        let inside = |x: V3| ring.inside([x[0].hypot(x[1]), x[2]], 0.0, 0.0).min(-d.any_slot(x, 0.0));
        (0..24)
            .map(|step| {
                let theta = TAU / zg * step as f64 / 24.0;
                let mut deepest = f64::MIN;
                for tooth in 0..zp as usize {
                    for left in [false, true] {
                        for row in pinion.flank(left, tooth) {
                            for q in row {
                                let qa = rot_z(k * theta, q);
                                let x = rot_z(-theta, d.pinion_to_design(qa));
                                deepest = deepest.max(inside(x));
                            }
                        }
                    }
                }
                deepest
            })
            .collect()
    }

    /// Turn the pair through mesh: pinion flank points never enter the
    /// ring gear, and some always touch it.
    #[test]
    fn pinion_flanks_run_against_the_ring_without_interference() {
        for offset in [30.0, 0.0] {
            let d = Spec { offset, ..car() }.design().unwrap();
            for (step, deepest) in deepest_through_mesh(&d).into_iter().enumerate() {
                assert!(deepest < 1e-6, "offset {offset}, step {step}: {deepest}");
                assert!(deepest > -0.05, "offset {offset}, step {step}: no contact ({deepest})");
            }
        }
    }

    /// Where the ball end mill can't get down the ring's curved slots,
    /// their floors are raised until it can, the more the more they curve;
    /// the pinion's tips come down to match, so the pair still runs
    /// without interference, its flanks touching.
    #[test]
    fn floors_are_raised_where_the_ball_cant_reach() {
        let hypoid = Spec { ball: 2.0, ..car() }.design().unwrap().reachable().unwrap();
        let spiral = Spec { offset: 0.0, ball: 2.0, ..car() }.design().unwrap().reachable().unwrap();
        let most = |d: &Design| d.floor.iter().copied().fold(0.0, f64::max);
        assert!(most(&hypoid) > 0.0 && most(&hypoid) < 0.25 * hypoid.depth, "{:?}", hypoid.floor);
        assert!(most(&spiral) > most(&hypoid), "{:?}", spiral.floor);
        for d in [&hypoid, &spiral] {
            let ring = d.ring().unwrap();
            let r = reach::check(&reach::member(&ring, d.spec.ball), d.spec.ball);
            assert!(r.share() < 0.01, "offset {}: {:.3} out of reach", d.spec.offset, r.share());
            for (step, deepest) in deepest_through_mesh(d).into_iter().enumerate() {
                assert!(deepest < 1e-6, "offset {}, step {step}: {deepest}", d.spec.offset);
                assert!(deepest > -0.05, "offset {}, step {step}: no contact ({deepest})", d.spec.offset);
            }
        }
        // No ball chosen: nothing raised.
        assert!(car().design().unwrap().reachable().unwrap().floor.is_empty());
    }

    /// Bevel worms: 3 to 7 starts on a near-face wheel, the shafts
    /// meeting or passing a little apart, run in mesh as the car set does,
    /// with more than a pitch of overlap.
    #[test]
    fn bevel_worms_run_against_their_wheels() {
        for (starts, offset) in [(3, 0.0), (5, 0.0), (7, 0.0), (3, 1.0), (4, 5.0), (6, 10.0), (7, -8.0)] {
            let spec = Spec {
                pinion_teeth: starts,
                ring_teeth: 30,
                module: 4.0,
                face: 18.0,
                offset,
                spiral: 50.0,
                backlash: 0.0,
                pinion_bore: 0.0,
                ring_bore: 30.0,
                nozzle: 0.0,
                ..car()
            };
            let d = spec.design().unwrap_or_else(|| panic!("{starts} starts, offset {offset}: no design"));
            assert!(d.face_contact_ratio() > 1.2, "{starts} starts, offset {offset}: {}", d.face_contact_ratio());
            d.ring().unwrap();
            for (step, deepest) in deepest_through_mesh(&d).into_iter().enumerate() {
                assert!(deepest < 1e-6, "{starts} starts, offset {offset}, step {step}: {deepest}");
                assert!(deepest > -0.05, "{starts} starts, offset {offset}, step {step}: no contact ({deepest})");
            }
        }
    }

    #[test]
    fn teeth_run_continuously_across_the_face() {
        // Neighbouring sections of tooth 0 sit well under a pitch apart.
        for spec in [car(), Spec { offset: 0.0, ..car() }] {
            let d = spec.design().unwrap();
            for m in [d.ring().unwrap(), d.pinion().unwrap()] {
                for k in 1..m.stations.len() {
                    let step = m.right[k][0][1] - m.right[k - 1][0][1];
                    assert!(step.abs() < m.pitch() / 3.0, "{} teeth, section {k}: {step}", m.teeth);
                }
            }
        }
    }

    #[test]
    fn exported_pair_sits_in_mesh() {
        // The pinion's flanks, placed as the train solves and exports
        // them, run against the true ring gear without cutting into it.
        use crate::train::{Link, PitchUnit, Project};
        let mut p = Project::empty();
        let a = p.add_root(PitchUnit::Module.starter_hypoid(Role::Pinion), 10.0, -5.0);
        p.add_child(a, PitchUnit::Module.starter_hypoid(Role::Ring), Link::Hypoid);
        p.normalize();
        if let crate::train::Placement::Hypoid { angle, .. } = &mut p.gears[1].placement {
            *angle = 35.0;
        }
        let d = car().design().unwrap();
        let ring = d.ring_blank();
        let mut deepest = f64::MIN;
        for step in 0..6 {
            let drive = 0.37 + step as f64 * 0.11;
            let parts = crate::export::hypoids(&p, drive, None, |_| true, |_| None);
            let (pin, rg) = (&parts[0], &parts[1]);
            for tooth in 0..11 {
                for left in [false, true] {
                    for row in pin.member.flank(left, tooth) {
                        for q in row {
                            let x = pin.frame.apply(rot_z(pin.rot, q));
                            let f = rg.frame;
                            let rel = sub(x, f.origin);
                            let y = rot_z(-rg.rot, [dot(rel, f.x), dot(rel, f.y), dot(rel, f.z)]);
                            let v = ring.inside([y[0].hypot(y[1]), y[2]], 0.0, 0.0).min(-d.any_slot(y, 0.0));
                            deepest = deepest.max(v);
                        }
                    }
                }
            }
        }
        assert!(deepest < 1e-4 && deepest > -0.05, "deepest {deepest}");
    }

    #[test]
    fn both_gears_generate() {
        let d = car().design().unwrap();
        let t0 = std::time::Instant::now();
        let ring = d.ring().expect("ring");
        let t1 = std::time::Instant::now();
        let pinion = d.pinion().expect("pinion");
        println!("ring {:?}, pinion {:?}", t1 - t0, t1.elapsed());
        for m in [&ring, &pinion] {
            for k in 0..SECTIONS {
                let (r, l) = (&m.right[k], &m.left[k]);
                assert_eq!(r.len(), PROFILE_POINTS + 1);
                // Flanks meet at the slot bottom and part at the tip.
                assert!((l[0][1] - r[0][1] - m.pitch()).abs() < 1e-9);
                assert!(l[PROFILE_POINTS][1] > r[PROFILE_POINTS][1]);
            }
        }
    }

    /// A ball end mill set: both gears' roots are rounded for it, where
    /// the teeth are smallest (the toe) and in the middle, and the pair
    /// still runs without interference.
    #[test]
    fn roots_are_milled_by_the_ball() {
        let worm = Spec {
            pinion_teeth: 5,
            ring_teeth: 30,
            module: 4.0,
            face: 18.0,
            offset: 5.0,
            spiral: 50.0,
            pinion_bore: 0.0,
            ring_bore: 30.0,
            nozzle: 0.0,
            ball: 1.5,
            ..car()
        };
        for (name, spec) in [("hypoid", Spec { ball: 3.0, ..car() }), ("spiral bevel", Spec { offset: 0.0, ball: 2.4, ..car() }), ("bevel worm", worm)] {
            let d = spec.design().unwrap();
            assert_eq!(d.ball_trouble(), None, "{name}");
            assert!((d.cutter.edge - spec.ball / 2.0).abs() < 1e-12);
            for (what, m) in [("ring", d.ring().unwrap()), ("pinion", d.pinion().unwrap())] {
                for k in [0, SECTIONS / 2] {
                    let s = m.stations[k];
                    let (sg, cg) = m.blank.pitch.sin_cos();
                    // Square to the tooth: its spiral angle here, from how
                    // the slot bottom turns from section to section.
                    let turn = (m.right[k + 1][0][1] - m.right[k][0][1]) / (m.stations[k + 1] - s);
                    let spiral = (s * sg * turn).atan();
                    // Space 0: tooth -1's high side (tooth 0's, a pitch
                    // back) tip to slot bottom, then tooth 0's low side.
                    let r = |t: f64| (s * sg + t * cg) * spiral.cos().abs();
                    let seam = m.right[k][0][1];
                    let back = m.left[k].iter().rev().map(|&[t, phi]| [t, (phi - m.pitch() - seam) * r(t)]);
                    let pts: Vec<[f64; 2]> = back.chain(m.right[k][1..].iter().map(|&[t, phi]| [t, (phi - seam) * r(t)])).collect();
                    let fits = crate::gear::ball_fits_space(&pts, spec.ball / 2.0);
                    assert!(fits > 0.97, "{name} {what}, section {k}: only {fits:.3} of the ball fits");
                }
            }
            for (step, deepest) in deepest_through_mesh(&d).into_iter().enumerate() {
                assert!(deepest < 1e-6, "{name}, step {step}: {deepest}");
                assert!(deepest > -0.05, "{name}, step {step}: no contact ({deepest})");
            }
        }
    }

    #[test]
    fn a_ball_too_big_for_the_spaces_is_flagged() {
        let largest = car().largest_ball().unwrap();
        assert!(largest > 2.0, "{largest}");
        assert_eq!(Spec { ball: 0.98 * largest, ..car() }.design().unwrap().ball_trouble(), None);
        assert!(Spec { ball: 1.05 * largest, ..car() }.design().unwrap().ball_trouble().is_some());
    }
}









